impl FromJs for rune_kit::PaletteFocus {
    fn from_js(v: conv::Value) -> conv::Result<Self> {
        let (tag, payload) = conv::enum_tag(v, "PaletteFocus")?;
        match (tag.as_str(), payload) {
            ("Blue", _) => Ok(rune_kit::PaletteFocus::Blue),
            ("Accent", _) => Ok(rune_kit::PaletteFocus::Accent),
            ("Ink", _) => Ok(rune_kit::PaletteFocus::Ink),
            ("Custom", Some(p)) => Ok(rune_kit::PaletteFocus::Custom(conv::arg::<rune::Color>(p, "PaletteFocus.Custom")?)),
            (other, _) => Err(conv::err(format!("{other:?} isn't a {} variant (or lacks its value)", "PaletteFocus"))),
        }
    }
}
impl ToJs for rune_kit::PaletteFocus {
    fn to_js(self) -> conv::Result<conv::Value> {
        #[allow(unreachable_patterns)]
        match self {
            rune_kit::PaletteFocus::Blue => conv::ToJs::to_js("Blue"),
            rune_kit::PaletteFocus::Accent => conv::ToJs::to_js("Accent"),
            rune_kit::PaletteFocus::Ink => conv::ToJs::to_js("Ink"),
            rune_kit::PaletteFocus::Custom(a) => Ok(conv::tagged("Custom", a.to_js()?)),
            _ => Ok(conv::undefined()),
        }
    }
}

